CREATE TABLE categorias_equipamento (
    id BIGSERIAL PRIMARY KEY,
    nome VARCHAR(100) NOT NULL,
    slug VARCHAR(120) NOT NULL UNIQUE,
    descricao VARCHAR(255),
    icone VARCHAR(40) NOT NULL DEFAULT 'Package',
    campos JSONB NOT NULL DEFAULT '[]'::JSONB,
    sistema BOOLEAN NOT NULL DEFAULT FALSE,
    ativa BOOLEAN NOT NULL DEFAULT TRUE,
    ordem INTEGER NOT NULL DEFAULT 100,
    criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_categoria_campos_array CHECK (jsonb_typeof(campos) = 'array')
);

CREATE UNIQUE INDEX uq_categorias_equipamento_nome_normalizado
    ON categorias_equipamento (LOWER(nome));

