ALTER TABLE equipamentos
    ADD COLUMN atributos JSONB NOT NULL DEFAULT '{}'::JSONB,
    ADD COLUMN fornecedor VARCHAR(180),
    ADD COLUMN data_compra DATE,
    ADD CONSTRAINT chk_equipamento_atributos_objeto CHECK (jsonb_typeof(atributos) = 'object');
